/** `standard`: up is good. `inverted`: down is good (latency, error rate, churn). */
export type KpiSemantics = "inverted" | "neutral" | "standard";

export type KpiTone = "flat" | "negative" | "neutral" | "positive";

export type KpiMetricsInput = {
  previousValue?: number;
  semantics: KpiSemantics;
  targetValue?: number | null;
  value: number;
};

export type KpiMetrics = {
  delta: number;
  /** Relative change as a percentage point of previousValue. `null` when the
   * ratio is undefined (no previous value, or previous is zero). */
  deltaPercent: number | null;
  hasComparison: boolean;
  showTarget: boolean;
  targetProgress: number;
  tone: KpiTone;
};

function resolveTone(delta: number, semantics: KpiSemantics): KpiTone {
  if (semantics === "neutral") return "neutral";
  if (delta === 0) return "flat";

  const isGood = semantics === "standard" ? delta > 0 : delta < 0;
  return isGood ? "positive" : "negative";
}

/**
 * Pure derivation of comparison, tone and target progress from KPI props.
 * Kept separate from the card so the arithmetic can be unit tested without a DOM.
 */
export function computeKpiMetrics({
  previousValue,
  semantics,
  targetValue = null,
  value,
}: KpiMetricsInput): KpiMetrics {
  const hasComparison = previousValue != null;
  const delta = hasComparison ? value - previousValue : 0;
  const deltaPercent =
    hasComparison && previousValue !== 0 ? (delta / Math.abs(previousValue)) * 100 : null;
  const tone = resolveTone(delta, semantics);
  const showTarget = targetValue != null && targetValue !== 0;
  const targetProgress = showTarget
    ? Math.min(100, Math.max(0, (value / targetValue) * 100))
    : 0;

  return { delta, deltaPercent, hasComparison, showTarget, targetProgress, tone };
}

export const CHART_VERTICAL_PADDING = 4;

/**
 * Height of the lowest bar as a fraction of the drawable height.
 *
 * Bars are normalised against the series minimum, so without a floor the lowest
 * value maps to zero height. On a live feed the newest value is regularly the
 * new minimum, which made every fresh bar collapse into an invisible sliver.
 */
export const MIN_BAR_HEIGHT_RATIO = 0.18;

export type BarGeometry = {
  height: number;
  width: number;
  x: number;
  y: number;
};

type GeometryOptions = {
  height: number;
  padding?: number;
  width: number;
};

/**
 * Positions and sizes the bars of a sparkline. Kept separate from the component
 * so the scaling rules can be unit tested without a DOM.
 */
export function computeBarGeometry(
  data: number[],
  { height, padding = CHART_VERTICAL_PADDING, width }: GeometryOptions,
): BarGeometry[] {
  if (data.length === 0) return [];

  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min;
  const drawableHeight = height - padding * 2;
  const baseline = height - padding;
  const barWidth = Math.max(2, width / data.length - 2);

  return data.map((point, index) => {
    // A flat series has no spread to scale against; draw it at full height
    // rather than collapsing every bar onto the floor.
    const ratio = range === 0 ? 1 : (point - min) / range;
    const scaled = Math.min(1, MIN_BAR_HEIGHT_RATIO + (1 - MIN_BAR_HEIGHT_RATIO) * ratio);
    const barHeight = drawableHeight * scaled;

    return {
      height: barHeight,
      width: barWidth,
      x: (index / data.length) * width,
      y: baseline - barHeight,
    };
  });
}

"use client";

import { CHART_VERTICAL_PADDING, computeBarGeometry } from "./sparkline-geometry";

export type SparklineType = "bar" | "line";

const WIDTH = 120;
const HEIGHT = 40;

type SparklineProps = {
  data: number[];
  type?: SparklineType;
};

/**
 * Micro chart drawn as plain SVG from the data points. Stroke and fill follow
 * `currentColor`, which `.kpi-chart` sets per trend tone. Decorative by
 * design: the numbers next to it carry the information, so it is hidden from
 * assistive tech.
 *
 * Both entrances live in `styles/motion.css`, which also answers the
 * reduced-motion question. The bars carry their index so the stylesheet can
 * stagger them; nothing else about the animation reaches this file.
 */
export function Sparkline({ data, type = "line" }: SparklineProps) {
  if (data.length === 0) return null;

  if (type === "bar") {
    return (
      <svg aria-hidden="true" focusable="false" height={HEIGHT} width={WIDTH}>
        {computeBarGeometry(data, { height: HEIGHT, width: WIDTH }).map((bar, index) => (
          <rect
            fill="currentColor"
            height={bar.height}
            key={index}
            opacity={0.6}
            style={{ "--kpi-bar-index": index } as React.CSSProperties}
            width={bar.width}
            x={bar.x}
            y={bar.y}
          />
        ))}
      </svg>
    );
  }

  // One point has no span to draw a line across, and a polyline of one point
  // renders nothing. A dot says "one reading".
  if (data.length === 1) {
    return (
      <svg aria-hidden="true" focusable="false" height={HEIGHT} width={WIDTH}>
        <circle cx={WIDTH / 2} cy={HEIGHT / 2} fill="currentColor" r={2.5} />
      </svg>
    );
  }

  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min || 1;
  const drawableHeight = HEIGHT - CHART_VERTICAL_PADDING * 2;

  const lastIndex = data.length - 1;
  const points = data
    .map((point, index) => {
      const x = (index / lastIndex) * WIDTH;
      const y = HEIGHT - CHART_VERTICAL_PADDING - ((point - min) / range) * drawableHeight;
      return `${x},${y}`;
    })
    .join(" ");

  return (
    <svg aria-hidden="true" focusable="false" height={HEIGHT} width={WIDTH}>
      {/* `pathLength={1}` renormalises the line to a single unit so the
          stylesheet can draw it with a dash of 1, whatever the data does to its
          real length. */}
      <polyline
        fill="none"
        pathLength={1}
        points={points}
        stroke="currentColor"
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeWidth={2}
      />
    </svg>
  );
}

import type { KpiValuePart } from "./format-value";

type ValuePartsProps = {
  parts: KpiValuePart[];
};

/**
 * Renders formatted parts as typed spans so the KPI styles can give the digits, the
 * locale notation (currency symbol, percent sign, compact exponent) and the
 * measure unit their own typography. Formatting happens in the card, which lets
 * one set of parts feed both the hero value and the target footer.
 */
export function ValueParts({ parts }: ValuePartsProps) {
  return parts.map((part, index) => (
    <span
      className={`kpi-value-part kpi-value-part--${part.kind}`}
      // Parts have no stable identity: the same kind and value can repeat
      // within one number (thousands groups), so position is the only key.
      key={`${index}-${part.kind}-${part.value}`}
    >
      {part.value}
    </span>
  ));
}

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type ComponentPropsWithRef,
  type PointerEvent as ReactPointerEvent,
  type ReactNode,
} from "react";

import {
  formatPercentChange,
  formatValueParts,
  partsToText,
  type KpiFormat,
} from "./internal/format-value";
import {
  ArrowDownRightIcon,
  ArrowUpRightIcon,
  CheckIcon,
  CopyIcon,
  ExternalLinkIcon,
  MinusIcon,
} from "./internal/icons";
import { computeKpiMetrics, type KpiSemantics } from "./internal/metrics";
import { Sparkline, type SparklineType } from "./internal/sparkline";
import { ValueParts } from "./internal/value-parts";

export type { KpiSemantics } from "./internal/metrics";

export type KpiChartType = SparklineType | "none";

export type KpiProps = {
  /** Replaces the default "open in new tab" glyph of the action button. */
  actionIcon?: ReactNode;
  /** Accessible name of the action button. */
  actionLabel?: string;
  chartType?: KpiChartType;
  className?: string;
  /** Caption next to the trend badge. */
  comparisonLabel?: string;
  /** Announced via a polite status region after a successful copy. */
  copiedLabel?: string;
  /** Accessible name of the copy button. */
  copyLabel?: string;
  /** ISO 4217 code, used when `format` is `"currency"`. */
  currency?: string;
  /** Hover, focus or touch-tap details panel body. Feature is inactive when omitted. */
  details?: ReactNode;
  /** Accessible name of the details group. */
  detailsLabel?: string;
  format?: KpiFormat;
  /**
   * Fixed decimals for `number`, `currency`, `compact` and `percentage`.
   * Applied to the value and target. When omitted, each format keeps its own
   * default (`number`: locale default; `currency`: the currency's own decimals, none for a whole amount; `compact`: max 1;
   * `percentage`: 1–2).
   */
  fractionDigits?: number;
  /** Oldest value first. */
  historyData?: number[];
  isLoading?: boolean;
  /** BCP 47 tag driving number, currency and percentage formatting. */
  locale?: string;
  onActionClick?: () => void;
  previousValue?: number;
  semantics?: KpiSemantics;
  showCopyButton?: boolean;
  targetLabel?: string;
  /** Renders the progress footer when set. */
  targetValue?: number | null;
  title: string;
  value: number;
  /**
   * Measure unit (`"km/s"`) shown after the main value and both target-footer
   * values. Currency and percent affixes come from `format` instead, so they
   * stay locale-correct.
   */
  valueUnit?: string;
};

const COPIED_RESET_MS = 2000;
const DETAILS_OPEN_DELAY_MS = 500;
const DETAILS_CLOSE_DELAY_MS = 200;
const TOUCH_TAP_MOVE_TOLERANCE_PX = 8;

/** Stable identity for the default, so `Kpi` stays safe to wrap in `memo`. */
const NO_HISTORY: number[] = [];

/**
 * Self-contained KPI card: a title, one large value, an optional trend badge,
 * sparkline, target progress and a details panel revealed on hover, focus or tap.
 *
 * The folder is self-contained. It imports no design tokens, no `cn()`
 * helper and no sibling components; all styling lives in `styles/` behind the
 * `kpi-` class / token prefix and every import inside the folder is relative. Copy
 * `kpi/` into another project; it needs nothing beyond React.
 *
 * @example
 * <Kpi
 *   comparisonLabel="vs last month"
 *   format="currency"
 *   historyData={[38_100, 39_400, 41_200, 42_800]}
 *   previousValue={41_200}
 *   targetValue={50_000}
 *   title="Monthly recurring revenue"
 *   value={42_800}
 * />
 */
export function Kpi({
  actionIcon,
  actionLabel = "Open details",
  chartType = "line",
  className,
  comparisonLabel = "vs last period",
  copiedLabel = "Value copied",
  copyLabel = "Copy raw value",
  currency = "USD",
  details,
  detailsLabel = "Additional details",
  format = "number",
  fractionDigits,
  historyData = NO_HISTORY,
  isLoading = false,
  locale = "en-US",
  onActionClick,
  previousValue,
  semantics = "standard",
  showCopyButton = true,
  targetLabel = "Goal",
  targetValue = null,
  title,
  value,
  valueUnit,
}: KpiProps) {
  const [copied, setCopied] = useState(false);
  const progressLabelId = useId();
  const copyTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const detailsActive = details != null;

  const clearCopyTimer = useCallback(() => {
    if (copyTimerRef.current != null) {
      clearTimeout(copyTimerRef.current);
      copyTimerRef.current = null;
    }
  }, []);

  useEffect(() => () => clearCopyTimer(), [clearCopyTimer]);

  const handleCopy = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(String(value));
      clearCopyTimer();
      setCopied(true);
      copyTimerRef.current = setTimeout(() => {
        setCopied(false);
        copyTimerRef.current = null;
      }, COPIED_RESET_MS);
    } catch {
      // Clipboard access is unavailable (insecure origin, denied permission).
      // Silently keep the previous state rather than breaking the card.
    }
  }, [clearCopyTimer, value]);

  const rootClassName = ["kpi-theme", "kpi", className].filter(Boolean).join(" ");
  // With details, the shell is the root: `className` goes there, so placement
  // classes (a grid span, a margin) work the same with or without a panel.
  const cardClassName = detailsActive ? "kpi-theme kpi" : rootClassName;

  if (isLoading) {
    return (
      <div aria-busy="true" className={`${rootClassName} kpi--loading`}>
        <div className="kpi-skeleton kpi-skeleton--title" />
        <div className="kpi-skeleton kpi-skeleton--value" />
        <div className="kpi-skeleton kpi-skeleton--footer" />
      </div>
    );
  }

  const { delta, deltaPercent, hasComparison, showTarget, targetProgress, tone } =
    computeKpiMetrics({ previousValue, semantics, targetValue, value });

  const TrendIcon = delta > 0 ? ArrowUpRightIcon : delta < 0 ? ArrowDownRightIcon : MinusIcon;
  const showChart = historyData.length > 0 && chartType !== "none";
  const visibleDeltaPercent = formatPercentChange(deltaPercent, { locale });
  const signedDeltaPercent =
    deltaPercent == null ? null : formatPercentChange(deltaPercent, { locale, signed: true });

  const formatOptions = { currency, format, fractionDigits, locale, unit: valueUnit };
  const valueParts = formatValueParts(value, formatOptions);

  const card = (
    <div className={`${cardClassName} kpi--tone-${tone}`}>
      <div className="kpi-header">
        <h3 className="kpi-title">{title}</h3>

        <div className="kpi-actions">
          {showCopyButton ? (
            <KpiButton
              aria-label={copyLabel}
              className={copied ? "kpi-button--success" : undefined}
              onClick={handleCopy}
            >
              {copied ? <CheckIcon /> : <CopyIcon />}
            </KpiButton>
          ) : null}
          {onActionClick ? (
            <KpiButton aria-label={actionLabel} onClick={onActionClick}>
              {actionIcon ?? <ExternalLinkIcon />}
            </KpiButton>
          ) : null}
        </div>
      </div>

      <span aria-live="polite" className="kpi-sr-only" role="status">
        {copied ? copiedLabel : ""}
      </span>

      <div className="kpi-body">
        {/* Remounting on a new value replays the CSS fade in `.kpi-value-animate`. */}
        <span className="kpi-value kpi-value-animate" key={partsToText(valueParts)}>
          <ValueParts parts={valueParts} />
        </span>

        {hasComparison ? (
          <div className="kpi-trend">
            <span className="kpi-trend-badge">
              <TrendIcon size={10} />
              {signedDeltaPercent != null ? (
                <>
                  <span aria-hidden="true">{visibleDeltaPercent}</span>
                  <span className="kpi-sr-only">{signedDeltaPercent}</span>
                </>
              ) : (
                visibleDeltaPercent
              )}
            </span>
            <span className="kpi-trend-comparison">{comparisonLabel}</span>
          </div>
        ) : null}

        {showChart ? (
          <div className="kpi-chart">
            <Sparkline data={historyData} type={chartType} />
          </div>
        ) : null}
      </div>

      {showTarget ? (
        <div className="kpi-footer">
          <div className="kpi-footer-row">
            <span className="kpi-footer-label" id={progressLabelId}>
              {targetLabel}
            </span>
            <span className="kpi-footer-value">
              <ValueParts parts={valueParts} />
              <span className="kpi-value-part kpi-value-part--literal"> / </span>
              <ValueParts parts={formatValueParts(targetValue, formatOptions)} />
            </span>
          </div>
          <div
            aria-labelledby={progressLabelId}
            aria-valuemax={100}
            aria-valuemin={0}
            aria-valuenow={Math.round(targetProgress)}
            className="kpi-progress"
            role="progressbar"
          >
            {/* The fill's width and its entrance both live in the stylesheet;
                this passes the fraction and nothing else. */}
            <div
              className="kpi-progress-fill"
              style={{ "--kpi-progress": targetProgress / 100 } as React.CSSProperties}
            />
          </div>
        </div>
      ) : null}
    </div>
  );

  if (!detailsActive) return card;

  return (
    <KpiDetailsShell
      className={className}
      details={details}
      detailsLabel={detailsLabel}
      // Without a button inside, nothing in the card takes focus, and the
      // panel would be out of reach of a keyboard or a screen reader.
      focusLabel={showCopyButton || onActionClick ? undefined : title}
    >
      {card}
    </KpiDetailsShell>
  );
}

export type KpiDetailRow = {
  label: string;
  value: string;
};

type KpiDetailsProps = {
  rows: KpiDetailRow[];
};

/**
 * Ready-made label/value list for the details panel. Pass it — or any other
 * node — into `Kpi`'s `details` prop; the card never fetches data itself.
 */
export function KpiDetails({ rows }: KpiDetailsProps) {
  if (rows.length === 0) return null;

  return (
    <dl className="kpi-details-list">
      {rows.map((row) => (
        <div className="kpi-details-row" key={row.label}>
          <dt className="kpi-details-label">{row.label}</dt>
          <dd className="kpi-details-value">{row.value}</dd>
        </div>
      ))}
    </dl>
  );
}

type KpiDetailsShellProps = {
  children: ReactNode;
  className?: string;
  details: ReactNode;
  detailsLabel: string;
  /** When set, the shell itself takes focus, named by this. */
  focusLabel?: string;
};

type TouchPress = {
  pointerId: number;
  startX: number;
  startY: number;
};

/** Whether focus came from a keyboard. An engine without `:focus-visible` says yes. */
function isKeyboardFocus(target: EventTarget | null): boolean {
  if (!(target instanceof Element)) return true;
  try {
    return target.matches(":focus-visible");
  } catch {
    return true;
  }
}

function isTouchToggleTarget(target: EventTarget | null): boolean {
  if (!(target instanceof Element)) return false;

  return target.closest(".kpi-details, a, button, input, select, textarea, [contenteditable], [role='button'], [role='link']") == null;
}

/** Owns open/close timers so omitting `details` unmounts and resets state. */
function KpiDetailsShell({
  children,
  className,
  details,
  detailsLabel,
  focusLabel,
}: KpiDetailsShellProps) {
  const [open, setOpen] = useState(false);
  const detailsId = useId();
  const openTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const closeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const touchPressRef = useRef<TouchPress | null>(null);
  const shellRef = useRef<HTMLDivElement>(null);
  /** A panel a tap opened closes on a tap, a press outside or Escape — not on blur. */
  const openedByTapRef = useRef(false);

  const clearTimers = useCallback(() => {
    if (openTimerRef.current != null) {
      clearTimeout(openTimerRef.current);
      openTimerRef.current = null;
    }
    if (closeTimerRef.current != null) {
      clearTimeout(closeTimerRef.current);
      closeTimerRef.current = null;
    }
  }, []);

  const scheduleOpen = useCallback(() => {
    openedByTapRef.current = false;
    clearTimers();
    openTimerRef.current = setTimeout(() => setOpen(true), DETAILS_OPEN_DELAY_MS);
  }, [clearTimers]);

  const scheduleClose = useCallback(() => {
    clearTimers();
    closeTimerRef.current = setTimeout(() => setOpen(false), DETAILS_CLOSE_DELAY_MS);
  }, [clearTimers]);

  const closeNow = useCallback(() => {
    openedByTapRef.current = false;
    clearTimers();
    setOpen(false);
  }, [clearTimers]);

  const handlePointerEnter = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
    if (event.pointerType !== "mouse") return;
    scheduleOpen();
  }, [scheduleOpen]);

  const handlePointerLeave = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
    if (event.pointerType !== "mouse") return;
    scheduleClose();
  }, [scheduleClose]);

  const handleTouchPointerDown = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
    if (event.pointerType !== "touch" || !isTouchToggleTarget(event.target)) return;

    touchPressRef.current = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
    };
  }, []);

  const handleTouchPointerCancel = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
    if (touchPressRef.current?.pointerId === event.pointerId) touchPressRef.current = null;
  }, []);

  const handleTouchPointerUp = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
    const touchPress = touchPressRef.current;
    touchPressRef.current = null;

    if (
      event.pointerType !== "touch" ||
      touchPress?.pointerId !== event.pointerId ||
      !isTouchToggleTarget(event.target) ||
      Math.hypot(event.clientX - touchPress.startX, event.clientY - touchPress.startY) > TOUCH_TAP_MOVE_TOLERANCE_PX
    ) return;

    clearTimers();
    openedByTapRef.current = !open;
    setOpen(!open);
  }, [clearTimers, open]);

  /*
   * While the panel is open, and only then: Escape closes it, and a press
   * anywhere outside the card does too — on a touch screen there is no pointer
   * to leave, so without it the panel stays over the page.
   *
   * Escape is taken in the capture phase on `window` and marked handled
   * (`defaultPrevented`), so a page handler that respects that — one that
   * closes a dialog or a view on Escape — does not act on the same key press.
   * Only when focus is in the card or on nothing: with focus in another
   * widget, the key is that widget's.
   */
  useEffect(() => {
    if (!open) return;

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== "Escape" || event.defaultPrevented) return;
      const active = document.activeElement;
      const shell = shellRef.current;
      if (active && active !== document.body && shell && !shell.contains(active)) return;
      event.preventDefault();
      closeNow();
    };
    const onPointerDown = (event: PointerEvent) => {
      const shell = shellRef.current;
      if (shell && event.target instanceof Node && !shell.contains(event.target)) closeNow();
    };

    window.addEventListener("keydown", onKeyDown, true);
    document.addEventListener("pointerdown", onPointerDown, true);
    return () => {
      window.removeEventListener("keydown", onKeyDown, true);
      document.removeEventListener("pointerdown", onPointerDown, true);
    };
  }, [closeNow, open]);

  useEffect(() => () => clearTimers(), [clearTimers]);

  return (
    <div
      aria-details={open ? detailsId : undefined}
      aria-label={focusLabel}
      className={["kpi-theme", "kpi-shell", className].filter(Boolean).join(" ")}
      onBlur={(event) => {
        const next = event.relatedTarget;
        // Tapping the card after a button in it moves focus off the button to
        // nothing; that blur must not close the panel the same tap just
        // opened. Focus that moves on to something else still closes it.
        if (openedByTapRef.current && next == null) return;
        if (next instanceof Node && event.currentTarget.contains(next)) return;
        scheduleClose();
      }}
      onFocus={(event) => {
        // Only keyboard focus opens the panel. A phone focuses the button it
        // taps, and a click focuses too; neither is a request for the panel,
        // and a mouse opens it by hovering. `:focus-visible` is the browser's
        // own answer to which focus came from a keyboard.
        if (!isKeyboardFocus(event.target)) return;
        scheduleOpen();
      }}
      onPointerCancel={handleTouchPointerCancel}
      onPointerDown={handleTouchPointerDown}
      onPointerEnter={handlePointerEnter}
      onPointerLeave={handlePointerLeave}
      onPointerUp={handleTouchPointerUp}
      ref={shellRef}
      role={focusLabel ? "group" : undefined}
      tabIndex={focusLabel ? 0 : undefined}
    >
      {children}
      <div
        aria-hidden={!open}
        aria-label={detailsLabel}
        className={`kpi-details kpi-details--animate${open ? " is-open" : ""}`}
        id={detailsId}
        role="group"
      >
        <div aria-hidden="true" className="kpi-details-bridge" />
        <div className="kpi-details-panel">
          <div className="kpi-details-content">{details}</div>
        </div>
      </div>
    </div>
  );
}

/** Icon-only action button; the accessible name comes from `aria-label`. */
function KpiButton({
  className,
  type = "button",
  ...props
}: ComponentPropsWithRef<"button">) {
  return (
    <button
      className={["kpi-button", className].filter(Boolean).join(" ")}
      type={type}
      {...props}
    />
  );
}

/* Layout, structure and static visuals for the KPI card and its details panel. */

.kpi {
  position: relative;
  display: flex;
  flex-direction: column;
  inline-size: 100%;
  block-size: 100%;
  padding: var(--kpi-padding);
  /* The card sizes its own contents by its width, not the viewport's: it may
   * sit in a narrow column on a wide screen. */
  container: kpi / inline-size;
  overflow: hidden;
  color: var(--kpi-foreground);
  font-family: var(--kpi-font-sans);
  background: var(--kpi-surface);
  border: 1px solid var(--kpi-border);
  border-radius: var(--kpi-radius);
  backdrop-filter: blur(var(--kpi-blur));

  /* `flat` keeps the muted default chart; `neutral` semantics get a brighter
   * line so the chart stays readable when direction carries no judgement. */
  &.kpi--tone-positive {
    --kpi-trend-color: var(--kpi-trend-color-override, var(--kpi-success));
    --kpi-chart-color: var(--kpi-chart-color-override, var(--kpi-success));
  }

  &.kpi--tone-negative {
    --kpi-trend-color: var(--kpi-trend-color-override, var(--kpi-destructive));
    --kpi-chart-color: var(--kpi-chart-color-override, var(--kpi-destructive));
  }

  &.kpi--tone-neutral {
    --kpi-chart-color: var(--kpi-chart-color-override, var(--kpi-muted-foreground));
  }
}

/* Host for the hover details overlay. Overflow stays visible so the panel can
 * hang below the card without expanding document flow. */
.kpi-shell {
  position: relative;
  display: block;
  inline-size: 100%;
  block-size: 100%;
  overflow: visible;
  interpolate-size: allow-keywords;
}

/* The shell takes focus itself only when the card has no button to reach the
 * panel through. */
.kpi-shell:focus-visible {
  outline: 2px solid var(--kpi-ring);
  outline-offset: 2px;
  border-radius: var(--kpi-radius);
}

.kpi-details {
  position: absolute;
  inset-block-start: 100%;
  inset-inline-start: 0;
  z-index: 20;
  inline-size: 100%;
  padding-block-start: 0.5rem;
  pointer-events: none;

  &.is-open {
    pointer-events: auto;

    & .kpi-details-panel {
      block-size: auto;
      opacity: 1;
      visibility: visible;
    }

    & .kpi-details-content {
      opacity: 1;
      transform: translateY(0);
    }
  }
}

.kpi-details-bridge {
  position: absolute;
  inset-block-start: 0;
  inset-inline: 0;
  block-size: 0.5rem;
}

/* Padding sits on the content wrapper so a padded panel can still collapse to
 * block-size: 0. */
.kpi-details-panel {
  block-size: 0;
  overflow: hidden;
  color: var(--kpi-foreground);
  font-family: var(--kpi-font-sans);
  background: var(--kpi-surface);
  border: 1px solid var(--kpi-border);
  border-radius: var(--kpi-radius);
  opacity: 0;
  /* Closed means gone for the keyboard too: a link passed in `details` must not
   * stay in the tab order behind an invisible panel. `motion.css` delays this
   * until the closing animation has run. */
  visibility: hidden;
  backdrop-filter: blur(var(--kpi-blur));
  box-shadow: 0 12px 32px color-mix(in oklab, var(--kpi-background) 55%, transparent);
}

.kpi-details-content {
  padding: 0.875rem 1rem;
  opacity: 0;
  transform: translateY(-0.75rem);
}

.kpi-details-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin: 0;
}

.kpi-details-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0.75rem;
  align-items: baseline;
}

.kpi-details-label {
  margin: 0;
  color: var(--kpi-muted-foreground);
  font-size: 0.75rem;
  line-height: 1.25;
}

.kpi-details-value {
  margin: 0;
  color: var(--kpi-foreground);
  font-size: 0.75rem;
  font-variant-numeric: tabular-nums;
  line-height: 1.25;
  text-align: end;
}

/* --- Header --------------------------------------------------------------- */

.kpi-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: flex-start;
  gap: 0.5rem;
  margin-block-end: 0.5rem;
}

/* The title keeps its local typeface even if a host styles headings directly. */
.kpi-title {
  /* Restated on the class, not only in the zero-specificity reset: a page's own
   * unlayered `h3` rule would otherwise win. */
  margin: 0;
  padding: 0;
  letter-spacing: normal;
  text-transform: none;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  color: var(--kpi-muted-foreground);
  font-weight: 500;
  font-size: 0.875rem;
  font-family: var(--kpi-font-sans);
  line-height: 1.25rem;
  white-space: nowrap;
  text-overflow: ellipsis;
}

/* Actions stay visible on coarse pointers. On hover-capable devices they are
 * revealed on hover / focus-within. */
.kpi-actions {
  display: flex;
  flex-shrink: 0;
  gap: 0.5rem;

  @media (hover: hover) {
    opacity: 0;
    transition: opacity var(--kpi-duration) ease;

    .kpi:hover &,
    .kpi:focus-within & {
      opacity: 1;
    }
  }
}

/* --- Action button ------------------------------------------------------- */

.kpi-button {
  /* As `.kpi-title`: what a page's own `button` rule would change. */
  margin: 0;
  padding: 0;
  min-inline-size: 0;
  min-block-size: 0;
  font: inherit;
  box-shadow: none;
  cursor: pointer;
  appearance: none;
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  inline-size: 1.5rem;
  block-size: 1.5rem;
  color: var(--kpi-muted-foreground);
  background: transparent;
  background-clip: padding-box;
  border: 1px solid transparent;
  border-radius: var(--kpi-radius-md);
  outline: none;
  transition:
    color var(--kpi-duration) ease,
    background-color var(--kpi-duration) ease,
    border-color var(--kpi-duration) ease,
    transform var(--kpi-duration) ease;
  user-select: none;

  & > svg {
    flex-shrink: 0;
    inline-size: 0.75rem;
    block-size: 0.75rem;
    pointer-events: none;
  }

  &:hover {
    color: var(--kpi-foreground);
    background: color-mix(in oklab, var(--kpi-muted) 50%, transparent);
  }

  &:focus-visible {
    /* Standard shadcn-style ring. A page may layer its own global focus
     * effect over it; the card never depends on one. */
    outline: 2px solid var(--kpi-ring);
    outline-offset: 2px;
  }

  &:active {
    transform: translateY(1px);
  }

  &.kpi-button--success {
    color: var(--kpi-success);
  }
}

/* --- Value + chart ------------------------------------------------------- */

.kpi-body {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin-block-start: 0.25rem;
}

.kpi-value {
  position: relative;
  z-index: 1;
  display: block;
  min-inline-size: 0;
  color: var(--kpi-foreground);
  font-weight: 700;
  font-size: 1.875rem;
  font-family: var(--kpi-font-mono);
  line-height: 1;
  letter-spacing: -0.025em;

  @container kpi (inline-size >= 20rem) {
    font-size: 2.25rem;
  }

  & .kpi-value-part--notation,
  & .kpi-value-part--unit {
    color: var(--kpi-foreground);
  }
}

.kpi-value-part--digits {
  font-variant-numeric: tabular-nums;
}

.kpi-trend {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  min-inline-size: 0;
  font-size: 0.875rem;
}

.kpi-trend-badge {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.125rem 0.375rem;
  color: var(--kpi-trend-color);
  font-weight: 500;
  font-family: var(--kpi-font-mono);
  font-variant-numeric: tabular-nums;
  background: var(--kpi-surface-muted);
  border: 1px solid var(--kpi-border-subtle);
  border-radius: var(--kpi-radius-sm);
}

.kpi-trend-comparison {
  color: var(--kpi-muted-foreground);
  font-size: 0.75rem;
}

.kpi-chart {
  position: absolute;
  inset-inline-end: 0;
  inset-block-end: 8px;
  z-index: 0;
  display: none;
  color: var(--kpi-chart-color);
  opacity: 0.8;
  transition: opacity var(--kpi-duration-slow) ease;
  pointer-events: none;

  .kpi:hover & {
    opacity: 1;
  }

  @container kpi (inline-size >= 20rem) {
    display: block;
  }
}

/* --- Target footer ------------------------------------------------------- */

.kpi-footer {
  margin-block-start: 1.5rem;
  padding-block-start: 1rem;
  border-block-start: 1px solid var(--kpi-border-subtle);
}

/* Label left, figures right — and when the two do not fit on one line, the
 * figures move to a line of their own rather than breaking in the middle.
 * "420.0 km/s / 500.0 km/s" split across two lines reads as two numbers; the
 * label can take a second line without changing what it says. */
.kpi-footer-row {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.125rem 1rem;
  margin-block-end: 0.375rem;
  font-size: 0.75rem;
}

.kpi-footer-label {
  flex: 1 1 auto;
  min-inline-size: 0;
  color: var(--kpi-muted-foreground);
}

.kpi-footer-value {
  margin-inline-start: auto;
  color: var(--kpi-muted-foreground);
  font-family: var(--kpi-font-mono);
  white-space: nowrap;
}

.kpi-progress {
  inline-size: 100%;
  block-size: 0.375rem;
  overflow: hidden;
  background: var(--kpi-muted);
  border-radius: 9999px;
}

.kpi-progress-fill {
  /* `--kpi-progress` is a unitless fraction written by the component; the bar
     is sized from it rather than from an inline width so the stylesheet owns
     both the resting size and how it gets there. `inline-size` and not a
     `scaleX` transform: the bar is six pixels tall, so there is no layout cost
     worth trading a logical property for, and this stays right in both writing
     directions. */
  inline-size: calc(var(--kpi-progress, 0) * 100%);
  block-size: 100%;
  background: var(--kpi-foreground);
  opacity: 0.55;
}

/* --- Loading skeleton --------------------------------------------------- */

.kpi--loading {
  gap: 1rem;
  min-block-size: 10rem;
}

.kpi-skeleton {
  background: var(--kpi-muted);
  border-radius: var(--kpi-radius-sm);

  &.kpi-skeleton--title {
    inline-size: 33%;
    block-size: 1rem;
  }

  &.kpi-skeleton--value {
    inline-size: 50%;
    block-size: 2.5rem;
  }

  &.kpi-skeleton--footer {
    inline-size: 25%;
    block-size: 0.75rem;
    margin-block-start: auto;
  }
}

/* --- Right-to-left ------------------------------------------------------ */

/* Layout is written in logical properties, so it follows `dir` on its own.
 * What does not is drawing: the trend arrow and the chart point along the
 * reading direction, so time runs from the inline start in both.
 *
 * The nearest `dir` decides, through an inherited factor, as the theme does.
 * Not `:dir(rtl)`: Vite and Next.js lower it to a list of `:lang()` selectors,
 * which answer to `lang`, not `dir`, so a page with only `dir="rtl"` would keep
 * its drawings unmirrored. */
:where([dir="rtl"]) {
  --kpi-mirror: -1;
}

:where([dir="ltr"]) {
  --kpi-mirror: 1;
}

.kpi-trend-badge svg,
.kpi-chart svg {
  transform: scaleX(var(--kpi-mirror, 1));
}

/* Motion: details open/close, chart entrances, value fade, loading pulse,
   reduced-motion.

   Every animation is CSS: a width, a rectangle and a line draw need no
   animation library, and the reduced-motion question is answered here, once,
   by the `prefers-reduced-motion` block at the foot of this file. The script
   never asks it. */

.kpi-details--animate {
  & .kpi-details-panel {
    transition:
      block-size var(--kpi-details-duration-out) ease-in,
      opacity var(--kpi-details-duration-out) ease-in,
      visibility 0s linear var(--kpi-details-duration-out);
  }

  & .kpi-details-content {
    transition:
      opacity calc(var(--kpi-details-duration-out) / 2) ease-in,
      transform var(--kpi-details-duration-out) ease-in;
  }

  &.is-open .kpi-details-panel {
    transition:
      block-size var(--kpi-details-duration-in) var(--kpi-details-ease),
      opacity 120ms ease-out,
      visibility 0s;
  }

  &.is-open .kpi-details-content {
    transition:
      opacity 200ms ease-out 60ms,
      transform var(--kpi-details-duration-in) var(--kpi-details-ease);
  }
}

/* --- Chart entrances ----------------------------------------------------- */

/*
 * The target bar fills from empty on first paint, and slides when the number
 * changes underneath it.
 *
 * A transition alone cannot do the first half: there is no previous value to
 * leave, so nothing interpolates on mount. The keyframe supplies that one, and
 * because it declares only `from`, the browser takes the element's own computed
 * size as the destination — no duplicate of the width in two places.
 */
.kpi-progress-fill {
  transition: inline-size var(--kpi-duration-progress) ease-out;
  animation: kpi-progress-fill var(--kpi-duration-progress) ease-out;
}

@keyframes kpi-progress-fill {
  from {
    inline-size: 0;
  }
}

/*
 * Sparkline bars rise from the baseline, each a beat after the one before it.
 *
 * `x`, `y`, `width` and `height` are CSS properties for SVG geometry, so the
 * rise is a keyframe rather than a per-frame write from JavaScript. The
 * baseline is the one literal here — `HEIGHT - CHART_VERTICAL_PADDING`, 40 − 4
 * — because a keyframe cannot read it off the element the way `from`-only
 * keyframes read a resting value.
 *
 * `backwards` holds the bar at zero through its stagger delay. Without it a bar
 * waiting its turn is drawn at full height and then jumps back down to start.
 */
.kpi-chart rect {
  transition:
    height var(--kpi-duration-bar) ease-out,
    y var(--kpi-duration-bar) ease-out;
  animation: kpi-bar-rise var(--kpi-duration-bar) cubic-bezier(0.22, 1, 0.36, 1) backwards;
  animation-delay: calc(var(--kpi-bar-index, 0) * var(--kpi-bar-stagger));
}

@keyframes kpi-bar-rise {
  from {
    height: 0;
    y: 36px;
  }
}

/*
 * The sparkline draws itself.
 *
 * The polyline carries `pathLength="1"`, which renormalises its own length to
 * one unit, so a dash of 1 is exactly the whole line whatever the data does to
 * its real length. Offsetting that dash out of view and back is the standard
 * line-draw, and it is what `pathLength: 0 → 1` was doing in the library.
 */
.kpi-chart polyline {
  stroke-dasharray: 1;
  animation: kpi-line-draw var(--kpi-duration-line) ease-in-out backwards;
}

@keyframes kpi-line-draw {
  from {
    stroke-dashoffset: 1;
    opacity: 0;
  }
  to {
    stroke-dashoffset: 0;
    opacity: 1;
  }
}

/* --- Everything else ----------------------------------------------------- */

@keyframes kpi-fade-in {
  from {
    opacity: 0.5;
    transform: translateY(-2px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.kpi-value-animate {
  animation: kpi-fade-in var(--kpi-duration-slow) ease-out forwards;
}

.kpi--loading {
  animation: kpi-pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}

@keyframes kpi-pulse {
  50% {
    opacity: 0.5;
  }
}

@media (prefers-reduced-motion: reduce) {
  .kpi,
  .kpi *,
  .kpi-shell,
  .kpi-shell * {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    /* Delays have to go too, not just durations. The sparkline bars stagger
       with `animation-delay` and hold at zero height through it — that is what
       `backwards` is for — so a bar whose duration collapsed but whose delay
       survived would sit invisible at the baseline, then appear. */
    transition-delay: 0ms !important;
    animation-delay: 0ms !important;
  }
}

/* Scoped reset: the element defaults the card relies on, whatever reset the
 * page has or lacks. Every selector uses `:where()` so specificity stays zero
 * and the card's own rules always win. A page's unlayered element rule
 * (`button { padding }`, `h3 { margin }`) beats zero specificity too, so the
 * properties that matter are restated on the card's classes in `layout.css`. */

:where(.kpi, .kpi-shell) {
  &,
  & :where(*, *::before, *::after) {
    box-sizing: border-box;
  }

  & :where(dl, dt, dd) {
    margin: 0;
  }
}

:where(.kpi) {
  & :where(h3, p, span, div, svg) {
    margin: 0;
    padding: 0;
  }

  & :where(button) {
    margin: 0;
    padding: 0;
    color: inherit;
    font: inherit;
    letter-spacing: inherit;
    background: none;
    border: 0;
    cursor: pointer;
    appearance: none;
  }

  & :where(svg) {
    display: block;
    overflow: visible;
  }
}

/* Visually hidden but announced by assistive tech. Absolute so it is not a
 * flex item and does not contribute to badge/action gaps. */
.kpi-sr-only {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  white-space: nowrap;
  border: 0;
  clip-path: inset(50%);
}

/* KPI theme, trimmed to the tokens the card actually consumes.
 *
 * Values are hardcoded Tailwind v4 slate (light) and zinc (dark) so this folder
 * stays portable and never imports host-site stylesheets. Tokens live on the
 * component root, not `:root`, so the card cannot replace the host's theme.
 *
 * Dark mode follows the nearest ancestor with `data-theme` or the `dark`
 * class, and the operating system without one. The component has no switch or
 * JavaScript theme listener of its own; a page can therefore give one
 * section its own light/dark choice without changing the rest.
 *
 * The switch is two inherited variables, not `light-dark()`. Vite and Next.js
 * lower `light-dark()` for older browsers into a polyfill that only works
 * beside a literal `color-scheme`, and the nearest-ancestor rule needs a
 * variable there, so a copied card built with either lost every colour.
 * Exactly one of `--kpi-light` and `--kpi-dark` is `initial`, which makes
 * `var()` take its fallback; the other is empty, which adds nothing. A colour
 * is therefore `var(--kpi-light, <light>) var(--kpi-dark, <dark>)`.
 */

:where([data-theme="light"]) {
  --kpi-color-scheme: light;
  --kpi-light: initial;
  --kpi-dark: ;
}

:where([data-theme="dark"], .dark) {
  --kpi-color-scheme: dark;
  --kpi-light: ;
  --kpi-dark: initial;
}

/* No light or dark theme around the card: the operating system decides. Only
 * those two values and the class count, so a page whose `data-theme` names
 * something else (`system`, a brand theme) still gets its colours. */
.kpi-theme:not(:is([data-theme="light"], [data-theme="dark"], .dark), :is([data-theme="light"], [data-theme="dark"], .dark) *) {
  --kpi-light: initial;
  --kpi-dark: ;

  @media (prefers-color-scheme: dark) {
    --kpi-light: ;
    --kpi-dark: initial;
  }
}

/* --- Light: Tailwind slate --------------------------------------------- */
.kpi-theme {
  --kpi-radius: var(--kpi-radius-override, 0.75rem);

  /* Tailwind's `rounded-sm` and `rounded-md`, without depending on Tailwind. */
