  --kpi-radius-md: var(--kpi-radius-md-override, 0.375rem);

  --kpi-background: var(--kpi-background-override, var(--kpi-light, oklch(98.4% 0.003 247.858)) var(--kpi-dark, oklch(14.1% 0.005 285.823))); /* slate-50 / zinc-950 */
  --kpi-foreground: var(--kpi-foreground-override, var(--kpi-light, oklch(12.9% 0.042 264.695)) var(--kpi-dark, oklch(98.5% 0 0))); /* slate-950 / zinc-50 */
  --kpi-card: var(--kpi-card-override, var(--kpi-light, oklch(100% 0 0)) var(--kpi-dark, oklch(21% 0.006 285.885))); /* white / zinc-900 */
