  --kpi-muted-foreground: var(--kpi-muted-foreground-override, var(--kpi-light, oklch(44.6% 0.043 257.281)) var(--kpi-dark, oklch(70.5% 0.015 286.067))); /* slate-600 / zinc-400 */
  --kpi-destructive: var(--kpi-destructive-override, var(--kpi-light, oklch(58.6% 0.253 17.585)) var(--kpi-dark, oklch(71.2% 0.194 13.428))); /* rose-600 / rose-400 */
  --kpi-success: var(--kpi-success-override, var(--kpi-light, oklch(59.6% 0.145 163.225)) var(--kpi-dark, oklch(76.5% 0.177 163.223))); /* emerald-600 / emerald-400 */
  --kpi-border: var(--kpi-border-override, var(--kpi-light, oklch(92.9% 0.013 255.508)) var(--kpi-dark, oklch(100% 0 0 / 10%))); /* slate-200 / white 10% */
  --kpi-ring: var(--kpi-ring-override, var(--kpi-light, oklch(70.4% 0.04 256.788)) var(--kpi-dark, oklch(55.2% 0.016 285.938))); /* slate-400 / zinc-500 */
  color-scheme: var(--kpi-color-scheme, light dark);
